INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, fees, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Bernards Township Summer Recreation Program', 'Bernards Township Recreation Department', 'https://www.bernards.org/departments/recreation', NULL, 'Recreation@Bernards.org', '908-204-3003', NULL, 'Basking Ridge', 'NJ', '07920', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['arts']::text[], ARRAY['arts and crafts','field days','theme days','educational activities','entertainers','spirit days']::text[], NULL, 5, 11, 0, 5, 'Six week township morning program for children entering kindergarten through grade 5 at three Bernards Township elementary schools (Liberty Corner, Mount Prospect and Oak Street), with arts and crafts, field days, theme days and visiting entertainers.', 'both', NULL, 600, 600, NULL, 'summer', FALSE, NULL, FALSE, NULL, 'Full refund less a $20 administrative fee per child if requested in writing before April 24, 2026 at 4:30 pm; no refunds after that or if a child is dismissed.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '1ef57dc8-f499-56c0-be2f-d8c7c030d556', 'bernards-township-summer-recreation-program-basking-ridge', ST_GeogFromText('SRID=4326;POINT(-74.5523 40.7062)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.bernards.org/departments/recreation','https://www.bernards.org/government/documents/forms-documents/department-documents/recreation/4450-2026-summer-recreation-program-parent-manual/file']::text[], '2026-11-27', '2026-11-27', TRUE),
('Blue Mountain Day Camp', 'Fairview Lake YMCA Camps (Metropolitan YMCA of the Oranges)', 'https://bluemountainymcacamp.org/', 'https://fairviewlakeymca.campbrainregistration.com/', 'bluemountain@metroymcas.org', '973-383-9282', 'Fairview Lake YMCA Camps, 1035 Fairview Lake Road', 'Stillwater', 'NJ', '07860', 'Northern New Jersey', 'day', ARRAY['general','outdoor']::text[], ARRAY['swimming','sailing','nature','sports','arts']::text[], ARRAY['swim lessons','free swim','paddleboarding','fishing','sailing','boating','climbing','hiking','archery','marksmanship','arts and crafts','candle making','survival skills','basketball','soccer','flag football','tennis','gaga','dance','drama and improv','trail rides']::text[], 'coed', 3, 15, NULL, NULL, 'Coed YMCA day camp on the Fairview Lake YMCA Camps property in Stillwater for ages 3 to 15, grouped from Turtles (age 3 to entering kindergarten) to Pioneers (entering grades 7 to 9). Campers take daily swim lessons in the lake and choose weekly clubs such as sailing, climbing, fishing, paddleboarding, hiking and survival skills.', 'both', NULL, 410, 740, 410, 'session', TRUE, TRUE, FALSE, TRUE, NULL, NULL, 'Daily swim lessons and an afternoon free swim in Fairview Lake, staffed by American Red Cross waterfront lifeguards and supervised by a Water Safety Instructor. Campers are swim tested on the first day.', TRUE, 'https://bluemountainymcacamp.org/about-camp', 2027, '[{"name": "Bus transportation", "amount": 152, "per": "session", "required": false, "note": "Two week Sessions 2 to 5; $79 for the one week Session 1. Three routes across Sussex County."}, {"name": "Before care", "amount": 89, "per": "session", "required": false, "note": "Two week Sessions 2 to 5; $47 for Session 1. Drop off from 7:30 a.m."}, {"name": "After care", "amount": 89, "per": "session", "required": false, "note": "Two week Sessions 2 to 5; $47 for Session 1. Pick up until 6 p.m."}, {"name": "Trail rides", "amount": 185, "per": "week", "required": false, "note": "Optional week of trail rides at the Fairview Lake Ranch, Pathfinders and Pioneers only", "source_url": "https://bluemountainymcacamp.org/schedule"}]'::jsonb, 'aa46a667-400d-542c-9de2-bc98a8282bd0', 'blue-mountain-day-camp-stillwater', ST_GeogFromText('SRID=4326;POINT(-74.8689 41.0741)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://bluemountainymcacamp.org/','https://bluemountainymcacamp.org/about-camp','https://bluemountainymcacamp.org/campinfo','https://bluemountainymcacamp.org/schedule']::text[], '2026-11-27', '2026-11-27', TRUE),
('Camp Nejeda', 'Camp Nejeda Foundation', 'https://www.campnejeda.org/', 'https://campnejeda.campbrainregistration.com/', 'information@campnejeda.org', '973-383-2611', '910 Saddleback Road', 'Stillwater', 'NJ', '07875', 'Northern New Jersey', 'sleepaway', ARRAY['special_needs']::text[], ARRAY['general','outdoor','swimming']::text[], ARRAY['zip line','climbing wall','low ropes course','archery','arts and crafts','basketball','baseball','gaga','soccer','volleyball','swimming','bonfires','evening activities']::text[], NULL, 7, 16, NULL, NULL, 'Sleepaway camp for children with type 1 diabetes on a 72 acre property in Stillwater, in one and two week sessions for ages 7 to 16. Campers do a zip line, climbing wall, low ropes, archery, sports and a daily pool swim, with round the clock nurses and an endocrinologist managing their diabetes care.', 'both', NULL, 1775, 3500, 1775, 'session', NULL, NULL, TRUE, TRUE, NULL, 'For children with type 1 diabetes. Nurses are on duty around the clock, a pediatric endocrinologist reviews blood sugars daily and adjusts insulin, and tech facilitators help with pump site and CGM changes. Most counselors have type 1 diabetes. Nut free camp with a dedicated gluten free prep space.', NULL, NULL, NULL, 2027, '[]'::jsonb, '2c196db7-057f-5769-bd71-6b6a705bfd37', 'camp-nejeda-stillwater', ST_GeogFromText('SRID=4326;POINT(-74.8689 41.0741)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.campnejeda.org/','https://www.campnejeda.org/future-campers/dates-and-rates','https://www.campnejeda.org/future-campers/financial-aid','https://www.campnejeda.org/sleep-away-camp']::text[], '2026-11-27', '2026-11-27', TRUE),
('Camp Wydaca', 'Wyckoff Family YMCA', 'https://wyckoffymca.org/index.php?src=gendocs&ref=2027-CampWydaca&category=CampWydaca', NULL, 'CampTeam@wyckoffymca.org', '201-891-2081', '691 Wyckoff Avenue', 'Wyckoff', 'NJ', '07481', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts','performing_arts','swimming','STEM']::text[], ARRAY['swimming','art','sports','theme activities','specialty camps','sing and dance','tennis','STEAM']::text[], NULL, 3, 14, NULL, 8, 'Wyckoff Family YMCA outdoor day camp for ages 3 through grade 8, with traditional and weekly specialty camps by grade. Every camper gets two swim periods a day at the Y''s Spring Lake Beach Club, plus art, sports on the turf and themed activities; specialty camps add sports, performing arts or STEAM periods.', 'outdoor', NULL, NULL, NULL, 460, 'week', TRUE, NULL, NULL, NULL, 'Deposits are not refundable and the Y gives no refunds. Changes are free through June 1, 2027, then cost $50 per camper per change; withdrawing after June 1 forfeits 50% of the week''s tuition (the rest becomes account credit), and within 5 business days of the week forfeits all of it.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Registration fee", "amount": 50, "per": "summer", "required": true, "note": "Per camper, not refundable"}, {"name": "After Camp Clubs", "amount": 100, "per": "week", "required": false, "note": "Grades 1 to 5, 4 to 5 pm; offsite tennis club $200 a week", "source_url": "https://wyckoffymca.org/index.php?src=gendocs&ref=2027-CampWydaca-ExtendedCampCare-ACC&category=CampWydaca"}]'::jsonb, '735d07c3-65b8-5e63-a6a2-18341ac99ba2', 'camp-wydaca-wyckoff', ST_GeogFromText('SRID=4326;POINT(-74.1688 40.9991)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://wyckoffymca.org/index.php?src=gendocs&ref=2027-CampWydaca&category=CampWydaca','https://wyckoffymca.org/index.php?src=gendocs&ref=2027-CampWydaca-ExtendedCampCare-ACC&category=CampWydaca','https://wyckoffymca.org/index.php?src=gendocs&ref=2027-CampWydaca-FAQS-PAYMENT&category=CampWydaca','https://wyckoffymca.org/index.php?src=gendocs&ref=2027-CampWydaca-GradeK&category=ViewAllCamps','https://wyckoffymca.org/index.php?src=gendocs&ref=2027-CampWydaca-LittleExplorers&category=ViewAllCamps','https://wyckoffymca.org/index.php?submenu=AboutUs&src=directory&view=locations&srctype=detail&refno=175&category=Branch']::text[], '2026-11-27', '2026-11-27', TRUE),
('Delbarton Sports Experience', 'Delbarton School', 'https://delbartonsummer.com/fs/pages/1828', 'https://delbartonsummer.campbrainregistration.com/', NULL, '973-538-3231', '230 Mendham Road', 'Morristown', 'NJ', '07960', 'Northern New Jersey', 'specialty', ARRAY['sports']::text[], '{}'::text[], ARRAY['soccer','football','basketball','lacrosse','tennis','baseball']::text[], 'boys', 8, 12, 3, 6, 'Weekly multi sport day camp at Delbarton School in Morristown for boys entering grades 3 to 6. Campers learn basic skills and rules in soccer, football, basketball, lacrosse, tennis and baseball through drills and games, coached by Delbarton students and coaches and college athletes.', 'both', NULL, 420, 420, 420, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '0b5a9564-f886-545b-a2f4-6633f915eabb', 'delbarton-sports-experience-morristown', ST_GeogFromText('SRID=4326;POINT(-74.4812 40.7968)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://delbartonsummer.com/fs/pages/1828','https://delbartonsummer.com/sports-camps/sports-camp-programs']::text[], '2026-11-27', '2026-11-27', TRUE),
('Eagles Sports Camp', 'Eastern Christian School', 'https://www.easternchristian.org/eagles-camps/our-camps/', 'https://www.easternchristian.org/eagles-camps/registration/', 'office@eaglescamps.org', '973-310-0421', '518 Sicomac Avenue', 'Wyckoff', 'NJ', '07481', 'Northern New Jersey', 'day', ARRAY['sports']::text[], NULL, ARRAY['kickball','baseball','soccer','basketball','battle ball','capture the flag','kick the can','water play']::text[], NULL, 6, 14, 1, 8, 'Neighborhood style sports day camp run by Eastern Christian School at its Wyckoff campus for children entering grades 1 to 8. Days are filled with kickball, baseball, soccer, basketball, capture the flag and water games.', 'both', NULL, 375, 375, 375, 'week', NULL, NULL, FALSE, NULL, 'A nonrefundable 40% deposit per camper per week holds the spot. Written cancellations before June 1 may get a partial refund; none after June 1 except case by case for medical or family emergencies. Partial weeks are not prorated.', NULL, NULL, NULL, NULL, 2027, '[]'::jsonb, '22d0f578-ef26-52a2-9aeb-044a568ca648', 'eagles-sports-camp-wyckoff', ST_GeogFromText('SRID=4326;POINT(-74.1688 40.9991)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.easternchristian.org/eagles-camps/our-camps/','https://www.easternchristian.org/eagles-camps/policies/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Fairview Lake YMCA Camps', 'Metropolitan YMCA of the Oranges', 'https://fairviewlakeymca.org/sleepaway', 'https://fairviewlakeymca.campbrainregistration.com/', 'fairviewlake@metroymcas.org', '973-383-9282', '1035 Fairview Lake Road', 'Newton', 'NJ', '07860', 'Northern New Jersey', 'sleepaway', ARRAY['general','outdoor']::text[], ARRAY['swimming','sailing','adventure','leadership','nature']::text[], ARRAY['swimming','sailing','windsurfing','canoeing','kayaking','archery','target sports','hiking','arts and crafts','robotics','improv','soccer','pickleball','basketball','tennis','ultimate frisbee','campfires','horseback riding']::text[], NULL, 7, 17, 2, 11, 'YMCA overnight camp on Fairview Lake outside Newton for campers entering grades 2 to 11. Traditional camps (coed Minisink and Tupelo, boys'' Kittatinny, girls'' Laurel Ridge) live in cabins and choose daily land and lake activities; Ranch, Specialty, Adventure Trip and CIT programs run on the same property.', 'both', NULL, 1622, 4562, NULL, 'session', NULL, NULL, TRUE, TRUE, NULL, NULL, NULL, TRUE, 'https://fairviewlakeymca.org/hubfs/FVL%202027%20For%20Web.pdf?hsLang=en', 2027, '[]'::jsonb, 'a7d6dbb8-3028-5fc1-a37a-fbe610739c27', 'fairview-lake-ymca-sleepaway-camp-newton', ST_GeogFromText('SRID=4326;POINT(-74.7536 41.0515)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://fairviewlakeymca.org/future-campers','https://fairviewlakeymca.org/hubfs/FVL%202027%20For%20Web.pdf?hsLang=en','https://fairviewlakeymca.org/sleepaway','https://fairviewlakeymca.org/traditional']::text[], '2026-11-27', '2026-11-27', TRUE),
('Gateway YMCA Summer Day Camp, Elizabeth Branch', 'The Gateway Family YMCA', 'https://tgfymca.org/programs/camp/summer-day-camp/', 'https://operations.daxko.com/Online/10013/ProgramsV2/Home.mvc', NULL, '(908) 355-9622', '135 Madison Avenue', 'Elizabeth', 'NJ', '07201', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts','STEM']::text[], ARRAY['games','sports','arts and crafts','steam','outdoor play']::text[], NULL, 5, 14, NULL, 8, 'YMCA day camp at the Gateway Family YMCA Elizabeth Branch in Elizabeth for entering kindergarten through grade 8. Weekly sessions mix indoor and outdoor games, sports, arts and STEAM with learning loss prevention activities.', 'both', NULL, 298, 298, 298, 'week', NULL, NULL, FALSE, TRUE, 'No refunds or credits if a child does not attend or for absences; the $50 per week deposit is non-refundable.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, 'ea5d4257-7d52-5fc5-8587-8da3a3793352', 'gateway-ymca-summer-day-camp-elizabeth-branch-elizabeth', ST_GeogFromText('SRID=4326;POINT(-74.1935 40.6664)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://tgfymca.org/dev-2/download/20/child-development-early-learning/7329/2026-summer-camp-parent-handbook-2.pdf','https://tgfymca.org/locations/elizabeth-branch/','https://tgfymca.org/programs/camp/summer-day-camp/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Gateway YMCA Summer Day Camp, Five Points Branch', 'The Gateway Family YMCA', 'https://tgfymca.org/programs/camp/summer-day-camp/', 'https://operations.daxko.com/Online/10013/ProgramsV2/Home.mvc', NULL, '(908) 688-9622', '201 Tucker Avenue', 'Union', 'NJ', '07083', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts','STEM','swimming']::text[], ARRAY['games','sports','arts and crafts','steam','outdoor play','swimming']::text[], NULL, 3, 14, NULL, 8, 'YMCA day camp at the Gateway Family YMCA Five Points Branch in Union for ages 3 and 4 in preschool camp and children entering kindergarten through grade 8, with a sports camp for ages 8 to 13. Weekly sessions mix indoor and outdoor games, sports, arts and STEAM with learning loss prevention activities and swimming.', 'both', NULL, 349, 359, 349, 'week', NULL, NULL, FALSE, TRUE, 'No refunds or credits if a child does not attend or for absences; the $50 per week deposit is non-refundable.', NULL, 'Swimming is part of camp at the Five Points and Rahway branches only; campers bring a swimsuit and towel.', NULL, NULL, 2026, '[]'::jsonb, 'edca90f1-cd16-50c6-b8cd-98c7d6c923f0', 'gateway-ymca-summer-day-camp-five-points-branch-union', ST_GeogFromText('SRID=4326;POINT(-74.965 40.6322)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://tgfymca.org/dev-2/download/20/child-development-early-learning/7329/2026-summer-camp-parent-handbook-2.pdf','https://tgfymca.org/locations/five-points-branch/','https://tgfymca.org/programs/camp/summer-day-camp/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Gateway YMCA Summer Day Camp, Rahway Branch', 'The Gateway Family YMCA', 'https://tgfymca.org/programs/camp/summer-day-camp/', 'https://operations.daxko.com/Online/10013/ProgramsV2/Home.mvc', NULL, '(732) 388-0057', '1564 Irving Street', 'Rahway', 'NJ', '07065', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts','STEM','swimming']::text[], ARRAY['games','sports','arts and crafts','steam','outdoor play','swimming']::text[], NULL, 3, 14, NULL, 8, 'YMCA day camp at the Gateway Family YMCA Rahway Branch in Rahway for ages 3 and 4 in preschool camp and children entering kindergarten through grade 8. Weekly sessions mix indoor and outdoor games, sports, arts and STEAM with learning loss prevention activities and swimming.', 'both', NULL, 349, 349, 349, 'week', NULL, NULL, FALSE, TRUE, 'No refunds or credits if a child does not attend or for absences; the $50 per week deposit is non-refundable.', NULL, 'Swimming is part of camp at the Five Points and Rahway branches only; campers bring a swimsuit and towel.', NULL, NULL, 2026, '[]'::jsonb, '652f17c9-ecb4-574f-b8be-12e6070dd8ea', 'gateway-ymca-summer-day-camp-rahway-branch-rahway', ST_GeogFromText('SRID=4326;POINT(-74.2805 40.6072)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://tgfymca.org/dev-2/download/20/child-development-early-learning/7329/2026-summer-camp-parent-handbook-2.pdf','https://tgfymca.org/locations/rahway-branch/','https://tgfymca.org/programs/camp/summer-day-camp/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Kenilworth Summer Camp', 'Borough of Kenilworth Recreation', 'https://kenilworthborough.com/256/Summer-Camp', 'https://register.communitypass.net/boroughofkenilworth', NULL, NULL, 'Harding Elementary School', 'Kenilworth', 'NJ', '07033', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts','STEM']::text[], ARRAY['steam','sports','crafts','relays','team building','free play']::text[], NULL, 6, 13, 1, 7, 'Borough recreation day camp at Harding Elementary School in Kenilworth for children entering grades 1 to 7, with structured morning activities such as STEAM, sports, crafts and team building and camper''s choice in the afternoon. Five day or three day weeks, with after care at the Rec Center.', 'both', NULL, 100, 160, 160, 'week', TRUE, NULL, NULL, NULL, 'Full refund less a $10 administrative fee if withdrawal notice is given at least 5 days before the start of the program or week.', NULL, NULL, NULL, NULL, 2026, '[{"name": "After care (3 to 6 pm, Rec Center)", "amount": 80, "per": "week", "required": false, "note": "Non-resident rate for 5 days; $48 for 3 days. Residents $40 (5 days) or $24 (3 days)."}]'::jsonb, '22063676-17f8-56ea-becd-c7ba00139c16', 'kenilworth-summer-camp-kenilworth', ST_GeogFromText('SRID=4326;POINT(-74.2881 40.6781)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://kenilworthborough.com/256/Summer-Camp']::text[], '2026-11-27', '2026-11-27', TRUE),
('Little Falls Summer Camp', 'Township of Little Falls Recreation Department', 'https://littlefallsnj.gov/index.asp?SEC=43A098E8-F38D-4DBA-9618-2A63EC45F491', NULL, 'recreation@littlefallsnj.gov', '973-256-3884', NULL, 'Little Falls', 'NJ', '07424', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts']::text[], ARRAY['games','sports','arts and crafts','special events','field trips']::text[], NULL, NULL, NULL, NULL, 6, 'Township recreation day camp in Little Falls for children in pre-K through grade 6, open to residents and non-residents, with games, sports, crafts, special events and optional field trips. Families pick and pay for single weeks.', NULL, NULL, 100, 175, 175, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[{"name": "After care (2 to 5 pm, grades 1 to 6)", "amount": 60, "per": "week", "required": false, "note": "Limited to 40 campers."}, {"name": "Field trip", "amount": 50, "per": "day", "required": false, "note": "Each trip $50 or $60 per child, 40 spots per trip, by grade; registered separately.", "source_url": "https://littlefallsnj.govoffice.com/uploads/dm/80331/LF_SummerCamp_FieldTrip26_2.pdf"}]'::jsonb, '46e41e30-e53d-5c37-a208-c415b54dbaaa', 'little-falls-summer-camp-little-falls', ST_GeogFromText('SRID=4326;POINT(-74.2174 40.8756)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://littlefallsnj.gov/index.asp?SEC=43A098E8-F38D-4DBA-9618-2A63EC45F491','https://littlefallsnj.govoffice.com/uploads/dm/80331/LF_SummerCamp_FieldTrip26_2.pdf','https://littlefallsnj.govoffice.com/uploads/dm/80332/LF_SummerCamp_Camper26_2.pdf']::text[], '2026-11-27', '2026-11-27', TRUE),
('STEM+ Explorers', 'Montclair Kimberley Academy', 'https://www.mka.org/stepintosummer/stemexplorers', 'https://mkamssummer.campbrainregistration.com/', 'mkasummer@mka.org', NULL, 'MKA Upper School Campus, 6 Lloyd Road', 'Montclair', 'NJ', '07042', 'Northern New Jersey', 'specialty', ARRAY['STEM']::text[], ARRAY['technology','arts']::text[], ARRAY['experimental science','robotics','engineering','3D printing','laser cutting','coding','podcasting','architecture','filmmaking','audio engineering','music making','animation','field trips']::text[], NULL, 11, 15, 6, 9, 'Four week STEM program at Montclair Kimberley Academy''s Upper School for rising 6th to 9th graders, taken by the week. Mornings are core courses in lab science, fabrication, engineering and coding plus an arts elective; afternoons are a weekly team design challenge that opens with a field trip.', 'indoor', NULL, 425, 850, 850, 'week', FALSE, FALSE, FALSE, NULL, 'Full refund less the non-refundable $125 deposit until February 28; 50% refund less the deposit from March 1; no refunds after March 31.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, 'edfa7061-eb96-50b0-8bf6-cb0c1db8c6c1', 'mka-stem-explorers-montclair', ST_GeogFromText('SRID=4326;POINT(-74.209 40.8262)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=6+Lloyd+Road%2C+Montclair%2C+NJ&benchmark=Public_AR_Current&format=json','https://www.mka.org/stepintosummer/stemexplorers','https://www.mka.org/stepintosummer/stemexplorers/faq']::text[], '2026-11-27', '2026-11-27', TRUE),
('Plainfield YMCA Camp RISE', 'Greater Somerset County YMCA', 'https://www.gscymca.org/child-care-camps/plainfield-camp/', 'https://operations.daxko.com/Online/5029/ProgramsV2/Search.mvc?category_ids=CAT1436', NULL, NULL, 'Cedarbrook School, 1049 Central Avenue', 'Plainfield', 'NJ', '07060', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['arts','sports','swimming','academic','leadership']::text[], ARRAY['arts and crafts','sports','games','dance','weekly swim','theme days','academic enrichment']::text[], NULL, 5, 17, 0, 11, 'YMCA day camp at Cedarbrook School in Plainfield for campers entering kindergarten through grade 8, with arts, sports and games, a daily learning block, weekly swim at the Bridgewater YMCA pool, and a counselor in training program for grades 9 to 11. Lunch and snack are included.', 'both', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, 'Full refund for cancellations before May 1, 2026; after that the Y keeps a $50 cancellation fee per week per child and refunds the rest. Documented medical reasons are the only exception.', NULL, 'Weekly swim time at the Bridgewater YMCA indoor pool, with transport to the Y on Fridays included; Kindercamp also gets weekly swim lessons and recreational swims at Plainfield outdoor pools.', NULL, NULL, 2026, '[]'::jsonb, 'a062a497-ed3a-5ddc-a3c1-1b4249417b14', 'plainfield-ymca-camp-rise-plainfield', ST_GeogFromText('SRID=4326;POINT(-74.4158 40.6154)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.gscymca.org/child-care-camps/plainfield-camp/']::text[], '2026-11-27', '2026-11-27', TRUE),
('YWCamp@Dumont', 'YWCA Northern New Jersey', 'https://ywcannj.org/summer-camp/', 'https://ywcannj.org/wp-content/uploads/2026/02/2026-Dumont-Application-Fill-.pdf', 'campregistration@ywcannj.org', '201-881-1700', 'Grant Elementary School, 100 Grant Avenue', 'Dumont', 'NJ', '07628', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['arts','nature','performing_arts','swimming']::text[], ARRAY['arts and crafts','nature exploration','theater','drama','field games','swimming','water play']::text[], NULL, 5, 12, NULL, NULL, 'YWCA day camp at Grant Elementary School in Dumont for children 5 to 12. Campers do arts and crafts, nature, theater, field games and water play, with reading and math woven into the activities.', 'both', NULL, 248, 310, 310, 'week', TRUE, NULL, NULL, TRUE, 'Registration and weekly fees are not refundable; changes cost a $25 processing fee.', NULL, NULL, TRUE, 'https://ywcannj.org/summer-camp/', 2026, '[{"name": "Registration", "amount": 35, "per": "once", "required": true}, {"name": "Pre camp", "amount": 55, "per": "week", "required": false, "note": "7:30 to 8:30 am; $44 for the short first week", "source_url": "https://ywcannj.org/wp-content/uploads/2026/02/2026-Dumont-Application-Fill-.pdf"}, {"name": "Post camp", "amount": 60, "per": "week", "required": false, "note": "5 to 6:30 pm; $48 for the short first week", "source_url": "https://ywcannj.org/wp-content/uploads/2026/02/2026-Dumont-Application-Fill-.pdf"}]'::jsonb, '8daf5bda-1095-56b7-81f5-6370648f7ccb', 'ywcamp-dumont-dumont', ST_GeogFromText('SRID=4326;POINT(-73.9924 40.9452)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ywcannj.org/summer-camp/','https://ywcannj.org/wp-content/uploads/2026/02/2026-Dumont-Application-Fill-.pdf']::text[], '2026-11-27', '2026-11-27', TRUE),
('Camp America', 'Camp America', 'https://camp-america.com/', NULL, 'wearecampamerica@gmail.com', '215-822-6313', '341 Lower State Road', 'Chalfont', 'PA', '18914', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','swimming','arts','adventure','STEM']::text[], ARRAY['swimming','swim lessons','soccer','basketball','tennis','pickleball','softball','volleyball','street hockey','gaga','rock climbing','zip lines','ropes course','ninja course','arts and crafts','pottery','wood shop','drama','dance','gymnastics','cooking','pony riding','go karts','mini golf','archery','boating','fishing','nature and science']::text[], NULL, 2, 15, NULL, NULL, 'Family run day camp in Chalfont, Bucks County, for more than 50 years, serving ages 2 1/2 to 15 from preschool camp to a counselor in training program. Campers have instructional and free swim daily across several pools and rotate through sports, climbing and zip lines, arts, wood shop, drama, go karts, ponies, boating and fishing; a STEAM track (STARS) is offered for ages 7 to 12.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, NULL, NULL, NULL, 'Instructional and recreational swim every day with Red Cross certified instructors, in small groups by level; four pools, two water slides and two diving boards.', NULL, NULL, 2026, '[]'::jsonb, '831e6b7b-1aea-5a4a-9f0e-b10b5b7c9342', 'camp-america-chalfont', ST_GeogFromText('SRID=4326;POINT(-75.2096 40.289)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://camp-america.com/','https://camp-america.com/ca-experience/','https://camp-america.com/current-families/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Camp Laughing Waters', 'Girl Scouts of Eastern Pennsylvania', 'https://www.gsep.org/en/members/for-girl-scouts/camp-and-outdoors/our-camp-locations/camp-laughing-waters.html', NULL, 'memberservices@gsep.org', NULL, '300 Hildebeidel Road', 'Gilbertsville', 'PA', '19525', 'Philadelphia, PA', 'sleepaway', ARRAY['general','outdoor']::text[], ARRAY['adventure','swimming','nature']::text[], ARRAY['horseback riding','hiking','creek adventures','outdoor cooking','swimming','low ropes','high ropes','disc golf','arts and crafts','climbing wall','bouldering','gaga','basketball','archery','campfires']::text[], 'girls', 6, 18, 1, 12, 'Girl Scouts of Eastern Pennsylvania''s largest overnight camp, on more than 400 acres in Gilbertsville, Montgomery County, for girls entering grades 1 to 12. Known for horseback riding, it also has a pool, high and low ropes, a climbing wall, disc golf and Swamp Creek to explore; campers sleep in cabins or platform tents.', 'outdoor', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, TRUE, NULL, NULL, 'Campers take a swim test at the start of the week and are grouped by ability; canoeing and off camp water trips need American Red Cross level 2.', NULL, NULL, 2026, '[{"name": "Girl Scout membership", "amount": 45, "per": "year", "required": true, "source_url": "https://www.gsep.org/en/members/for-girl-scouts/camp-and-outdoors/camp-fa-application.html", "note": "Campers must be registered GSEP Girl Scouts; unregistered campers pay $45 at drop off. GSEP''s financial aid page says the 2027 member year (October 2026 to September 2027) costs $25 per girl."}, {"name": "Camp bus from Philadelphia (one way trip)", "amount": 55, "per": "once", "required": false, "note": "Sunday and Friday trips sold separately, each $55; stops at Northeast Towers and 56th and Chestnut."}]'::jsonb, '600555a5-d41f-565a-ab34-3d58cf8190e9', 'camp-laughing-waters-gilbertsville', ST_GeogFromText('SRID=4326;POINT(-75.6086 40.323)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.gsep.org/content/dam/gsep-redesign/documents/camp-and-properties/camp-confirmation-packets-/my26/Camp%20Laughing%20Waters%20confirmation%20packet.pdf','https://www.gsep.org/en/members/for-girl-scouts/camp-and-outdoors/camp-fa-application.html','https://www.gsep.org/en/members/for-girl-scouts/camp-and-outdoors/our-camp-locations/camp-laughing-waters.html']::text[], '2026-11-27', '2026-11-27', TRUE),
('Camp Meadowbrook', 'The Meadowbrook School', 'https://themeadowbrookschool.org/camp-meadowbrook', NULL, 'summercamps@themeadowbrookschool.org', '215-884-3238', '1641 Hampton Rd', 'Abington', 'PA', '19046', 'Philadelphia, PA', 'day', ARRAY['academic','general']::text[], NULL, NULL, NULL, 3, 12, NULL, NULL, 'Weekly summer programs on The Meadowbrook School campus for children 3 to 12, each built around age appropriate, academically based activities. Little Adventurers serves the youngest campers and specialty camps run by the week.', NULL, NULL, 375, 495, NULL, 'week', FALSE, NULL, NULL, TRUE, '90% refund until March 15 and 40% until April 15, each less a 10% processing fee, for accounts paid in full; deposits are non-refundable.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '413c8d28-5a20-512a-b8dd-358fee7fa4c1', 'camp-meadowbrook-meadowbrook', ST_GeogFromText('SRID=4326;POINT(-75.1142 40.1136)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://themeadowbrookschool.org/__l5e/assets-v1/f907aa06-8b33-4b61-a4b7-1abd807fc158/camp-faqs.pdf','https://themeadowbrookschool.org/camp-meadowbrook']::text[], '2026-11-27', '2026-11-27', TRUE),
('Camp Shelly Ridge', 'Girl Scouts of Eastern Pennsylvania', 'https://www.gsep.org/en/members/for-girl-scouts/camp-and-outdoors/our-camp-locations/camp-shelly-ridge.html', NULL, 'memberservices@gsep.org', NULL, '330 Manor Road', 'Springfield', 'PA', '19444', 'Philadelphia, PA', 'day', ARRAY['general','outdoor']::text[], ARRAY['swimming','arts','adventure']::text[], ARRAY['swimming','archery','hiking','climbing wall','bouldering','arts and crafts','gaga','low ropes','outdoor cooking','theme weeks','campfires']::text[], 'girls', 6, 18, 1, 12, 'Girl Scout day and overnight camp at the council''s Shelly Ridge headquarters in Lafayette Hill, next to Chestnut Hill and Roxborough, for girls entering grades 1 to 12. Days include the pool, archery, hiking, climbing and low ropes, crafts and theme weeks; overnight campers sleep in a lodge or platform tents.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, TRUE, NULL, NULL, 'Campers take a swim check at the start of the week in each section of the pool and are grouped by ability; some activities need a set swim level.', NULL, NULL, 2026, '[{"name": "Girl Scout membership", "amount": 45, "per": "year", "required": true, "source_url": "https://www.gsep.org/en/members/for-girl-scouts/camp-and-outdoors/camp-fa-application.html", "note": "Campers must be registered GSEP Girl Scouts; unregistered campers pay $45 at drop off. GSEP''s financial aid page says the 2027 member year (October 2026 to September 2027) costs $25 per girl."}, {"name": "Extended care (4:30 to 6 PM)", "amount": 85, "per": "week", "required": false}, {"name": "Shelly Ridge Swim Club (4 to 5 PM group lesson)", "amount": 100, "per": "week", "required": false, "note": "Swim Club plus extended care is $150 per week."}, {"name": "Day camp bus from Philadelphia stops (round trip)", "amount": 85, "per": "week", "required": false}, {"name": "Day Camp Sleepover (week of August 10 only)", "amount": 60, "per": "session", "required": false}]'::jsonb, '21d3f21c-3edc-5b02-998d-653446793ad5', 'camp-shelly-ridge-lafayette-hill', ST_GeogFromText('SRID=4326;POINT(-76.7345 41.8637)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.gsep.org/en/discover/our-council/contact.html','https://www.gsep.org/en/members/for-girl-scouts/camp-and-outdoors/camp-fa-application.html','https://www.gsep.org/en/members/for-girl-scouts/camp-and-outdoors/our-camp-locations/camp-shelly-ridge.html']::text[], '2026-11-27', '2026-11-27', TRUE),
('Center School Summer Learning & Enrichment Program', 'Center School', 'https://www.centerschoolpa.org/apps/pages/summer-learning', NULL, NULL, '215-657-2200', '2450 Hamilton Ave', 'Abington', 'PA', '19001', 'Philadelphia, PA', 'specialty', ARRAY['academic']::text[], ARRAY['STEM','arts','special_needs']::text[], ARRAY['literacy','math','science experiments','coding with Ozobots','stop motion animation','art','CrossFit fitness','mindfulness','team sports']::text[], NULL, NULL, NULL, 1, 8, 'Four week program at Center School in Abington for students entering grades 1 to 8 from any school. Mornings bring small group literacy and math instruction; the full day option adds afternoon STEAM enrichment with science, coding, art, fitness and mindfulness.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 'Written cancellations by June 1, 2026 are refunded minus a 10% fee; no refunds after June 1.', 'Center School serves students with dyslexia, dysgraphia, dyscalculia, auditory processing disorder, ADHD and executive function challenges; it cannot support students who need one to one wraparound behavioral services all day.', NULL, NULL, NULL, 2026, '[]'::jsonb, 'e4b3ec7d-da97-58bd-9487-24740b24bdf6', 'center-school-summer-learning-and-enrichment-program-abington', ST_GeogFromText('SRID=4326;POINT(-75.1142 40.1136)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.centerschoolpa.org/apps/pages/summer-learning']::text[], '2026-11-27', '2026-11-27', TRUE),
('Cindy Griffin Basketball Camps', 'Saint Joseph''s University Women''s Basketball', 'https://www.cindygriffinbasketballcamps.com/summer-camps.html', 'https://portal.campnetwork.com/Register/Register.php?camp_id=396745', NULL, NULL, 'Hagan Arena, 2450 N. 54th Street', 'Philadelphia', 'PA', '19131', 'Philadelphia, PA', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['basketball','shooting drills','stations','relay races','3 on 3','1 on 1','games']::text[], NULL, 5, 14, NULL, NULL, 'Week long summer basketball camps at Saint Joseph''s University''s Hagan Arena: a coed morning camp for ages 5 to 8 and a full day fundamentals camp for girls 9 to 14, built around skill stations, drills and games.', 'indoor', NULL, 250, 375, NULL, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '[]'::jsonb, '05cb75a4-7952-5a45-9674-ee32e623e725', 'cindy-griffin-basketball-camps-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.cindygriffinbasketballcamps.com/contact.html','https://www.cindygriffinbasketballcamps.com/summer-camps.html']::text[], '2026-11-27', '2026-11-27', TRUE),
('Elmwood Park Zoo Camp', 'Elmwood Park Zoo', 'https://elmwoodparkzoo.org/education/zoo-camp/', NULL, 'camp@elmwoodparkzoo.org', '610-277-3825', '1661 Harding Blvd', 'Norristown', 'PA', '19401', 'Philadelphia, PA', 'day', ARRAY['nature']::text[], ARRAY['STEM','outdoor']::text[], ARRAY['animal encounters','zoo walks','keeper chats','giraffe feeding','crafts','science exploration','behind the scenes tours','exhibit design','animal enrichment']::text[], NULL, 3, 12, NULL, NULL, 'Week long zoo camp at Elmwood Park Zoo in Norristown for ages 3 to 12, in four age groups from a half day preschool camp to Future Keepers. Campers meet ambassador animals, walk the zoo, feed giraffes and learn how keepers care for animals through crafts and hands on activities.', 'outdoor', NULL, 350, 450, 450, 'week', TRUE, NULL, FALSE, NULL, 'Purchases made in the December 2026 holiday sale, School''s Out Day Camp purchases and any early or after care are not refundable.', 'Campers must be fully potty trained and able to stay with a group outdoors all day. The zoo works with families on accommodations in advance (email camp@elmwoodparkzoo.org) but cannot provide one on one support; aides hired by families may attend after clearances.', NULL, NULL, NULL, 2027, '[{"name": "Early drop off (8 to 8:30 AM, full day groups)", "amount": 75, "per": "week", "required": false}, {"name": "Late pick up (4 to 4:50 PM, full day groups)", "amount": 150, "per": "week", "required": false}]'::jsonb, '723b7b88-9181-5058-8158-5fbb3bd5cc68', 'elmwood-park-zoo-camp-norristown', ST_GeogFromText('SRID=4326;POINT(-75.3399 40.1221)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://elmwoodparkzoo.org/education/zoo-camp/','https://www.elmwoodparkzoo.org/camp-faq/']::text[], '2026-11-27', '2026-11-27', TRUE),
('EPIC Day Camp at Germantown Friends School', 'Germantown Friends School', 'https://www.germantownfriends.org/community/summer-camps', 'https://campscui.active.com/orgs/GermantownFriendsSchool?orglink=camps-registration', 'camps@germantownfriends.org', '267-323-3474', '31 W. Coulter Street', 'Philadelphia', 'PA', '19144', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['arts','STEM','swimming','outdoor']::text[], ARRAY['music and dance','STEM','outdoor adventure','makerspace','art','library visits','water play','swimming']::text[], 'coed', 3, 9, NULL, NULL, 'Five week themed day camp at Germantown Friends School''s main campus for children 3 to 9, rising preschool through grade 3. Campers have specials in music, dance, STEM, art and outdoor adventure, library visits, and water play or swimming at Germantown Cricket Club for the older groups.', 'both', NULL, 360, 475, 475, 'week', NULL, TRUE, NULL, NULL, 'Full refund within 48 hours of registering; after that a $100 cancellation fee per session; no refunds on or after May 4, 2026.', NULL, NULL, NULL, NULL, 2026, '[{"name": "Center City shuttle (601 Walnut Street, through July 17)", "amount": 125, "per": "week", "required": false}]'::jsonb, '0e759bac-5ffc-5188-ba9a-bb3b3d065b56', 'epic-day-camp-at-germantown-friends-school-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=31+W.+Coulter+Street%2C+Philadelphia%2C+PA&benchmark=Public_AR_Current&format=json','https://www.germantownfriends.org/community/summer-camps']::text[], '2026-11-27', '2026-11-27', TRUE),
('Falcon Hill Camp', 'Holy Child School at Rosemont', 'https://www.holychildrosemont.org/student-experience/summer-camps', NULL, 'dmoorehead@holychildrosemont.org', '215-554-6168', '1344 Montgomery Avenue', 'Rosemont', 'PA', '19010', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['academic','sports','performing_arts','STEM']::text[], ARRAY['story time','arts and crafts','games','nature walks','water play','sports','musical theater','science','literacy','math']::text[], 'coed', 3, 13, NULL, NULL, 'Weekly camps at Holy Child School at Rosemont for boys and girls 3 to 13: Falcon and Kinder Camps for young children, Fun Camp sports and games for rising grades 1 to 7, plus one week theater, science, literacy, math and study skills camps. Open to all families.', NULL, 'Catholic', 275, 500, 450, 'week', TRUE, NULL, FALSE, NULL, 'A $100 non-refundable deposit per camper per week at registration; no refunds or credits for cancelled weeks after March 22, 2026, and none for absences.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '66e9b2b1-e29f-5155-9b7a-8684a2eb5fff', 'falcon-hill-camp-rosemont', ST_GeogFromText('SRID=4326;POINT(-75.327 40.0306)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.holychildrosemont.org/student-experience/summer-camps']::text[], '2026-11-27', '2026-11-27', TRUE),
('George School Day Camp', 'George School', 'https://www.georgeschool.org/community-programs/summer/gsdc', 'https://georgeschoolcamps.campbrainregistration.com/', 'gsdc4kids@georgeschool.org', '215-579-6692', '1690 Newtown Langhorne Road', 'Newtown', 'PA', '18940', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts']::text[], ARRAY['swimming lessons','games','arts and crafts','nature trails','tennis','field trips','variety show']::text[], 'coed', 4, 14, NULL, NULL, 'Day camp on George School''s 240 acre campus in Newtown for children 4 to 14, grouped by grade. Campers have Red Cross swim lessons in the indoor pool, games, crafts, theme weeks and field trips, and lunch is provided.', 'both', NULL, 3940, 5475, NULL, 'summer', TRUE, NULL, TRUE, NULL, '$200 deposit is non-refundable. Cancel before May 15 for a refund minus the deposit; May 15 to 31, a $100 fee and 30% of tuition refunded; no refund after May 31.', NULL, 'Indoor 8 lane, 25 yard pool, 4 to 7 feet deep. Red Cross lessons at least 3 times a week with WSI instructors, pool time daily, no flotation devices.', NULL, NULL, 2027, '[{"name": "Before care (7:30 to 9 am)", "amount": 75, "per": "week", "required": false}, {"name": "After care (3:30 to 6 pm)", "amount": 90, "per": "week", "required": false}, {"name": "Drop in before or after care", "amount": 25, "per": "day", "required": false}]'::jsonb, '0b795fce-bb0e-5b11-b3bb-ef5e8f6f74d7', 'george-school-day-camp-newtown', ST_GeogFromText('SRID=4326;POINT(-74.9323 40.2283)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.georgeschool.org/community-programs/summer/gsdc','https://www.georgeschool.org/community-programs/summer/gsdc/dates-and-rates','https://www.georgeschool.org/community-programs/summer/gsdc/program-overview']::text[], '2026-11-27', '2026-11-27', TRUE),
('Hideaway Day Camp', 'Hideaway Day Camp', 'https://hideawaydaycamp.org/', 'https://hideawaydaycamp.org/sign-up-form/', NULL, '610-489-2191', '3471 Arcola Road', 'Collegeville', 'PA', '19426', 'Philadelphia, PA', 'day', ARRAY['general','outdoor']::text[], ARRAY['swimming','nature','adventure','arts']::text[], ARRAY['swimming','ropes courses','rock wall','zip line','canoeing','fishing','miniature golf','gaga','volleyball','basketball','drama','arts and crafts','hiking','nature study','archery','creek walks','cookouts']::text[], NULL, 5, 14, NULL, NULL, 'Traditional day camp since 1961 on 72 acres along the Skippack Creek near Valley Forge Park, for ages 5 to 14. Every group has a swim lesson each morning, then rotates through ropes courses, rock wall and zip line, canoeing and fishing, mini golf, archery, drama, crafts, nature study and creek walks.', 'outdoor', NULL, NULL, NULL, 560, 'week', TRUE, TRUE, FALSE, NULL, 'Written cancellation before March 1 refunds everything, including the $300 deposit; March 1 to April 1 refunds all but the deposit. Full payment due April 1, with no refunds after. Up to two weeks can be cancelled before April 1 without penalty; each further cancelled week costs $100. Switching weeks is free if space allows.', 'Hideaway tries to meet campers'' special needs; one on one or wraparound support must be arranged with the office before camp starts.', 'Every group has a mandatory swim lesson each morning; optional free swim in the afternoon for campers who took the lesson.', NULL, NULL, 2027, '[{"name": "Pizza Mondays", "amount": 7, "per": "week", "required": false, "source_url": "https://hideawaydaycamp.org/wp-content/uploads/2026/08/CAMPER-HANDBOOK-2027.pdf"}]'::jsonb, '0c517ecc-e545-519a-99f1-c9c7e8a1f48f', 'hideaway-day-camp-collegeville', ST_GeogFromText('SRID=4326;POINT(-75.4575 40.1869)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://hideawaydaycamp.org/','https://hideawaydaycamp.org/contact/faq/','https://hideawaydaycamp.org/wp-content/uploads/2026/08/CAMPER-HANDBOOK-2027.pdf']::text[], '2026-11-27', '2026-11-27', TRUE),
('Malvern Day Camp', 'The Malvern School', 'https://malverndaycamp.com/', 'https://daycareworks.com/registration/malverndaycamp/start_registration.jsp?centerID=8674', NULL, '610-558-3200', '20 Creek Road', 'Thornbury', 'PA', '19342', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','adventure']::text[], ARRAY['swimming','swim lessons','water park','waterfront','nature','steam','gaga','sports','adventure course','archery','rock wall','four square','tech station','arts and crafts']::text[], NULL, 5, 14, NULL, NULL, 'Day camp in Glen Mills for ages 5 to 14 in Mini, Junior and Senior camps plus a counselor in training program. Campers swim twice a day with optional lessons and rotate through sports, waterfront, nature, STEAM, archery, the rock wall and adventure course; families choose 2, 3 or 5 days a week for 3 to 10 weeks.', 'outdoor', NULL, 375, 610, 610, 'week', TRUE, TRUE, NULL, NULL, 'The $100 registration fee and $200 deposit are non-refundable. Tuition paid before March 15 can be refunded; no refunds for weeks cancelled after April 1, 2027, or for absences or early withdrawal.', NULL, NULL, TRUE, 'https://malverndaycamp.com/about/', 2027, '[{"name": "Registration fee", "amount": 100, "per": "summer", "required": true, "note": "Non-refundable."}, {"name": "Lunch", "amount": 8, "per": "day", "required": false, "source_url": "https://malverndaycamp.com/future-campers/lunch-snacks/", "note": "Ordered in the parent portal by the Thursday before each week. Two snacks a day are served."}]'::jsonb, '965152b8-b086-5af4-8d7c-b8f014af95a0', 'malvern-day-camp-glen-mills', ST_GeogFromText('SRID=4326;POINT(-75.5575 39.924)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://malverndaycamp.com/about/','https://malverndaycamp.com/about/faqs/','https://malverndaycamp.com/future-campers/camp-hours/','https://malverndaycamp.com/future-campers/dates-rates/','https://malverndaycamp.com/future-campers/directions/','https://malverndaycamp.com/future-campers/lunch-snacks/','https://malverndaycamp.com/future-campers/transportation/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Music Theatre Philly Weekly Summer Camps', 'Music Theatre Philly', 'https://www.musictheatrephilly.com/about-camps', NULL, NULL, '445-223-2683', 'MTP Studios, 1301 Locust Street', 'Philadelphia', 'PA', '19107', 'Philadelphia, PA', 'specialty', ARRAY['performing_arts']::text[], '{}'::text[], ARRAY['singing','dancing','acting','musical revue','crafts','games']::text[], NULL, 3, NULL, NULL, 6, 'Weekly musical theater camps at Music Theatre Philly''s Center City studios on Locust Street for ages 3 through rising 6th grade. Each week has a show theme; campers learn songs and choreography with professional teaching artists and perform a Friday showcase that is filmed for families.', 'indoor', NULL, 375, 575, 575, 'week', TRUE, NULL, FALSE, TRUE, 'Full refund less a $25 registration fee per class if cancelled more than two weeks before the session; 50% refund less the $25 within two weeks; no refund once the session starts.', NULL, NULL, NULL, NULL, 2027, '[{"name": "Before care", "amount": 75, "per": "week", "required": false, "note": "8 to 9 a.m.; $20 a day"}, {"name": "After care, grades 1 to 6", "amount": 120, "per": "week", "required": false, "note": "3 to 5:30 p.m. Monday to Thursday; $40 a day; none on Fridays", "source_url": "https://www.musictheatrephilly.com/1-6-camps"}, {"name": "After care, PreK to K", "amount": 225, "per": "week", "required": false, "note": "Noon to 3 p.m.; $60 a day"}]'::jsonb, 'a8d4215d-aafb-568d-adc6-47b5ca62efd7', 'music-theatre-philly-summer-camps-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.musictheatrephilly.com/1-6-camps','https://www.musictheatrephilly.com/about-camps','https://www.musictheatrephilly.com/prek-k-camps']::text[], '2026-11-27', '2026-11-27', TRUE),
('Penn Charter Day Camp', 'William Penn Charter School', 'https://www.penncharter.com/about/news/news-detail/~board/summer-camp/post/day-camp', 'https://penncharter.bravoenrollment.com/auth/login', NULL, '215-844-3460', '3000 West School House Lane', 'Philadelphia', 'PA', '19144', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','performing_arts']::text[], ARRAY['swimming lessons','free swim','tennis','art','archery','music','dance','drama','sports and games','electives']::text[], 'coed', 3, 13, NULL, NULL, 'Weekly day camp on Penn Charter''s 47 acre East Falls campus for children 3 to 13 who are toilet trained. Campers have swim lessons and free swim, tennis, archery, art, music, dance, drama, sports and electives; families pack lunch.', NULL, NULL, 495, 550, 550, 'week', TRUE, TRUE, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '1940c48a-cb85-5e68-8cdb-b919f9343083', 'penn-charter-day-camp-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.penncharter.com/about/news/news-detail/~board/summer-camp/post/day-camp','https://www.penncharter.com/summercamp']::text[], '2026-11-27', '2026-11-27', TRUE),
('Prep U', 'St. Joseph''s Preparatory School', 'https://www.sjprep.org/community/summer-programs', NULL, NULL, '215-978-1950', '1733 W. Girard Avenue', 'Philadelphia', 'PA', '19130', 'Philadelphia, PA', 'specialty', ARRAY['academic']::text[], ARRAY['sports','leadership']::text[], ARRAY['math','science','English','leadership','speaker series','theater workshops','clubs','intramural sports']::text[], 'coed', NULL, NULL, 7, 8, 'Three week middle school program at St. Joseph''s Prep in Philadelphia for boys and girls entering grades 7 and 8. Mornings have three core classes, then a daily speaker series, lunch and a rotating activity period of clubs and intramural sports.', NULL, NULL, 600, 1000, NULL, 'session', NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '[]'::jsonb, '87a0e6ad-2803-596f-a1a6-428960253367', 'prep-u-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.sjprep.org/community/summer-programs']::text[], '2026-11-27', '2026-11-27', TRUE),
('Seaport Summer Camp', 'Independence Seaport Museum', 'https://www.phillyseaport.org/camp/', NULL, 'camp@phillyseaport.org', '215-413-8655', '211 S. Columbus Blvd.', 'Philadelphia', 'PA', '19106', 'Philadelphia, PA', 'day', ARRAY['academic']::text[], ARRAY['outdoor','STEM','arts']::text[], ARRAY['history ship tours','on water time','rowing','kayaking','crafts','museum collection tours','boatshop tours','steam science','navigation','river ecology','cooking']::text[], NULL, 6, 11, NULL, NULL, 'Weekly themed day camp at the Independence Seaport Museum on Penn''s Landing for ages 6 to 11. Campers learn Philadelphia''s history through the Delaware River with crafts, tours of the cruiser Olympia and submarine Becuna, the boatshop and research center, and scheduled time out on the water.', 'both', NULL, 450, 450, 450, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '[{"name": "Aftercare (3 to 5:30 PM)", "amount": 150, "per": "week", "required": false}]'::jsonb, 'f945b667-21f6-586a-acb0-8eaaa7efc3ef', 'seaport-summer-camp-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.phillyseaport.org/camp/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Steve & Kate''s Camp at DVFriends', 'Steve & Kate''s Camp', 'https://www.dvfriends.org/apps/pages/summer', 'https://steveandkatescamp.com/paoli/', NULL, NULL, 'Delaware Valley Friends School, 19 E Central Avenue', 'Paoli', 'PA', '19301', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['arts','STEM']::text[], ARRAY['designing','building','creating','playing']::text[], NULL, 5, 13, NULL, NULL, 'Day camp run by Steve & Kate''s on the Delaware Valley Friends School campus in Paoli for ages 5 to 13, where campers choose their own activities and plan their days. Families buy day passes, with long hours and lunch and snacks included.', NULL, NULL, 118, 118, NULL, 'day', TRUE, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, 'e154f879-edd8-57d4-b56c-dd959e2b3599', 'steve-and-kates-camp-at-dvfriends-paoli', ST_GeogFromText('SRID=4326;POINT(-75.4903 40.042)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.dvfriends.org/apps/pages/summer']::text[], '2026-11-27', '2026-11-27', TRUE),
('Summer at AIM', 'AIM Academy', 'https://academy.aimpa.org/academics/summer-at-aim', 'https://academy.aimpa.org/fs/pages/4321', 'summer@aimpa.org', '215-483-2461', '1200 River Road', 'Conshohocken', 'PA', '19428', 'Philadelphia, PA', 'specialty', ARRAY['academic']::text[], ARRAY['special_needs']::text[], ARRAY['reading','writing','comprehension','math','project work']::text[], NULL, NULL, NULL, 1, 12, 'Four week summer program at AIM Academy in Conshohocken for students in grades 1 to 12 from any school. AIM teachers give small group instruction in reading, writing, comprehension and math with interactive projects, full day or mornings only.', NULL, NULL, 2800, 3800, NULL, 'session', TRUE, NULL, FALSE, FALSE, 'Full refund for withdrawal before May 1; after May 1 a full refund is not possible.', 'Built on AIM''s approach to language based learning differences, but no diagnosis is required. AIM says the program cannot serve cognitive impairment, needs on the autism spectrum, or emotional or behavioral conduct disorders. Non AIM students have a short virtual academic screening.', NULL, NULL, NULL, 2027, '[{"name": "Before care", "amount": 260, "per": "session", "required": false}, {"name": "After care", "amount": 260, "per": "session", "required": false}]'::jsonb, 'e94eb464-1b4c-5b49-8677-9d6b35174a37', 'summer-at-aim-conshohocken', ST_GeogFromText('SRID=4326;POINT(-75.3041 40.0772)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://academy.aimpa.org/academics/summer-at-aim']::text[], '2026-11-27', '2026-11-27', TRUE),
('Summer at Baldwin Day Camp', 'The Baldwin School', 'https://www.baldwinschool.org/about/summer-at-baldwin/summer-at-baldwin-information', NULL, 'summer@baldwinschool.org', '610-525-2700', '701 Montgomery Avenue', 'Bryn Mawr', 'PA', '19010', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['arts','sports','swimming','nature']::text[], ARRAY['creative arts','sports','swimming lessons','themed activities','special events','field trips','nature exploration']::text[], 'coed', 4, 12, NULL, 6, 'Themed weekly day camp at The Baldwin School in Bryn Mawr for girls and boys from rising pre-K through grade 6. Campers do arts, sports, swim lessons, nature explorations and special events, with field trips in four of the seven weeks.', NULL, NULL, 600, 650, 650, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '[{"name": "After care until 5 pm", "amount": 200, "per": "week", "required": false}, {"name": "Daily after care until 5 pm", "amount": 40, "per": "day", "required": false}]'::jsonb, '6c5b836e-635b-5c24-b8c7-1096ce3091b6', 'summer-at-baldwin-bryn-mawr', ST_GeogFromText('SRID=4326;POINT(-75.3162 40.0208)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.baldwinschool.org/about/summer-at-baldwin','https://www.baldwinschool.org/about/summer-at-baldwin/summer-at-baldwin-information']::text[], '2026-11-27', '2026-11-27', TRUE),
('Summer Camp at Honey Hollow', 'Honey Hollow Nature Center', 'https://www.honeyhollownaturecenter.org/summer-camp-2026/', NULL, 'Info@HoneyHollowNatureCenter.org', '215-297-5880', '2877 Creamery Road', 'New Hope', 'PA', '18938', 'Philadelphia, PA', 'day', ARRAY['nature']::text[], ARRAY['outdoor','STEM']::text[], ARRAY['nature exploration','hands on science','creek play','animal encounters','fossil digs','fairy houses','insect study','wetland exploration','games']::text[], NULL, 4, 12, NULL, NULL, 'Nature day camp on Honey Hollow''s 55 acre preserve of meadows, forests, ponds and streams near New Hope. A half day Nature Exploration Camp serves ages 4 to 6 and the Summer Adventure Camp serves ages 6 to 12, with a new theme each week mixing outdoor exploration, science, games and free time outside.', 'outdoor', NULL, 240, 395, 395, 'week', NULL, NULL, NULL, NULL, 'Full payment at registration. Cancel 30 or more days before camp for a full refund, 14 to 29 days for half; no refund within two weeks.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '403f2931-9ee8-5867-81b2-270eb7115b1d', 'summer-camp-at-honey-hollow-new-hope', ST_GeogFromText('SRID=4326;POINT(-74.9568 40.3614)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.honeyhollownaturecenter.org/summer-camp-2026/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Summer Camp at The Waldorf School of Philadelphia', 'The Waldorf School of Philadelphia', 'https://phillywaldorf.com/summer-camps', 'https://campscui.active.com/orgs/WaldorfSchoolofPhiladelphia?orglink=camps-registration', 'summercamp@phillywaldorf.com', '215-248-1662', '6000 Wayne Avenue', 'Philadelphia', 'PA', '19144', 'Philadelphia, PA', 'day', ARRAY['general','nature']::text[], ARRAY['arts','outdoor','sports']::text[], ARRAY['water play','stories','gardening','crafts','games','weekly outing','woodwork','outdoor skills','sports']::text[], NULL, 3, 14, NULL, NULL, 'Weekly day camp led by Waldorf teachers on the school''s wooded Germantown campus for ages 3 to 14. Summergarten (ages 3 to 5) plays outdoors with water play and stories, Camp Wonder (grades 1 to 3) gardens, crafts and goes on a weekly outing, and Wonder Studios (grades 4 to 8) picks a studio such as woodwork, outdoor skills or sports each week.', 'both', NULL, 499, 549, 499, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '[]'::jsonb, 'd2f4dc12-2adf-50e0-b62a-5a3267daea13', 'summer-camp-at-the-waldorf-school-of-philadelphia-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://phillywaldorf.com/info-registration','https://phillywaldorf.com/summer-camps']::text[], '2026-11-27', '2026-11-27', TRUE),
('Summer Clay Camps', 'The Clay Studio', 'https://www.theclaystudio.org/camp-policies', 'https://public.theclaystudio.org/public/3/camps', 'education@theclaystudio.org', '215-925-3453', '1425 N. American Street', 'Philadelphia', 'PA', '19122', 'Philadelphia, PA', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['clay sculpture','wheel throwing','claymation','collage','drawing','mixed media']::text[], NULL, 6, 18, 1, 12, 'Week long clay camps at The Clay Studio''s building in South Kensington for youth entering grades 1 to 12, in small classes led by teaching artists: sculpture, wheel throwing and claymation, with some weeks of drawing and mixed media. Half day morning or afternoon camps can be paired for a full day, and Fridays end with a show of the week''s work.', 'indoor', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, TRUE, 'Cancel at least 7 days before camp for a full refund less a $25 processing fee; no refunds within 7 days or for missed days. The first switch to another camp is free. A $100 non-refundable deposit holds a spot if not paying in full.', NULL, NULL, NULL, NULL, 2026, '[{"name": "Supervised lunch (12 to 1 PM, half day campers)", "amount": 20, "per": "week", "required": false, "note": "Free for campers in both a morning and an afternoon camp; food not included."}, {"name": "Extended Creative Care (4 to 6 PM)", "amount": 50, "per": "week", "required": false}]'::jsonb, '9f8bca13-97d1-5c29-8c16-815466dea5e1', 'the-clay-studio-summer-clay-camps-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://public.theclaystudio.org/public/3/camps','https://www.theclaystudio.org/camp-policies']::text[], '2026-11-27', '2026-11-27', TRUE),
('West Norriton Township Summer Day Camp', 'West Norriton Township Parks & Recreation', 'https://westnorritontwp.org/138/Summer-Camp', NULL, 'sdinolfi@wntwp.com', '610-630-1251', 'Marshall Street Elementary School, 1525 West Marshall Street', 'West Norriton', 'PA', '19403', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','arts']::text[], ARRAY['arts and crafts','sports','guest presentations','day trips']::text[], 'coed', 5, 13, NULL, NULL, 'Seven week township day camp at Marshall Street Elementary School for children 5 to 13 who have finished kindergarten. Campers do arts and crafts, daily sports and weekly guest presentations, with optional day trips; camp meets Monday to Thursday only.', NULL, NULL, 550, 550, NULL, 'summer', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '6c2ec4e5-4f7a-57a0-8e1f-f1668a1aa6de', 'west-norriton-township-summer-day-camp-west-norriton', ST_GeogFromText('SRID=4326;POINT(-75.3775 40.1309)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=1525+West+Marshall+Street%2C+West+Norriton%2C+PA&benchmark=Public_AR_Current&format=json','https://westnorritontwp.org/138/Summer-Camp']::text[], '2026-11-27', '2026-11-27', TRUE),
('Buchanan Day Camp', 'Village of Buchanan Recreation Department', 'https://buchananny.gov/_documents/recreation/2026-Camp-Registration.pdf', NULL, 'jpasquale@buchananny.gov', '914-293-8391', NULL, 'Buchanan', 'NY', '10511', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts']::text[], ARRAY['swim lessons','free swim','art','kickball','dodgeball','volleyball','basketball','gaga','water slides','board games']::text[], NULL, 5, 14, 0, 8, 'Six week village day camp for children entering kindergarten to 8th grade, open to residents and non-residents, run in two three week sessions from 9 to 3. Mornings include swim lessons at the village pool, afternoons free swim, with art, field sports, gaga and special guests; after care runs to 6.', 'both', NULL, 523, 996, NULL, 'session', TRUE, NULL, NULL, NULL, 'No refunds, including for weather cancellations. Full payment is due at registration.', NULL, 'Swim lessons each morning by a WSI and lifeguard staff and afternoon free swim at the village pool; every camper is swim assessed in the first two days. A signed swim permission slip is required.', NULL, NULL, 2026, '[]'::jsonb, '250d878e-109c-58a0-a570-f1b10ce11559', 'buchanan-day-camp-buchanan', ST_GeogFromText('SRID=4326;POINT(-73.945 41.2632)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://buchananny.gov/_documents/recreation/2026-Camp-Registration.pdf']::text[], '2026-11-27', '2026-11-27', TRUE),
('Camp Saw Mill', 'Saw Mill Club', 'https://www.sawmillclub.com/kids/camp-saw-mill/', 'https://form.jotform.com/253634821451152', 'whitney.kennedy@genesishealthclubs.com', '914-733-4038', '77 Kensico Dr', 'Mount Kisco', 'NY', '10549', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','sports']::text[], ARRAY['swimming','tennis','playgrounds','crafts','dress up parades','face painting','animal visits','science experiments','sprinklers']::text[], NULL, 3, 11, NULL, 5, 'Day camp for young children at the Saw Mill Club in Mount Kisco, from a 3 year old group through 5th grade, with daily swim instruction in an outdoor pool reserved for campers, group tennis, playgrounds, crafts and special events. Half and full days, 3 to 5 days a week, minimum two weeks.', NULL, NULL, 450, 695, 695, 'week', NULL, NULL, NULL, NULL, 'Camp fees, less the $400 non-refundable deposit and the 2.95% processing fee, are refunded only for withdrawals before May 15, 2026; no refunds or make ups after that.', NULL, 'Outdoor pool reserved for campers with daily assisted swim instruction, plus a kiddie pool.', NULL, NULL, 2026, '[]'::jsonb, 'ef6b05e7-63fa-5919-8a0c-226a0e4ef4f8', 'camp-saw-mill-mount-kisco', ST_GeogFromText('SRID=4326;POINT(-73.7237 41.2023)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.sawmillclub.com/kids/camp-saw-mill/','https://www.sawmillclub.com/wp-content/uploads/2026/01/SMC-Summer-Camp-2026-B.pdf']::text[], '2026-11-27', '2026-11-27', TRUE),
('Hole-in-One Junior Golf Camp at Dunwoodie', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/golf-childrens-camp', 'https://sales.westchestergov.com/webtrac/web/search.html?module=AR&TYPE=GOLF&search=Yes', NULL, '(914) 231-3490', '1 Wasylenko Ln', 'Yonkers', 'NY', '10701', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['golf']::text[], NULL, 7, 17, NULL, NULL, 'County junior golf camp at Dunwoodie golf course: four two hour lessons Monday to Thursday with a PGA professional, in separate weeks for ages 7 to 11 and 12 to 17. Campers learn the fundamentals and build skills; bringing clubs is encouraged but not required.', 'outdoor', NULL, 125, 125, 125, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, 'fb123287-bf26-5e3d-a24f-8985faa6a0fd', 'hole-in-one-junior-golf-camp-dunwoodie-yonkers', ST_GeogFromText('SRID=4326;POINT(-73.8988 40.9312)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/golf-childrens-camp']::text[], '2026-11-27', '2026-11-27', TRUE),
