('Katonah Art Center Summer Camps', 'Katonah Art Center', 'https://www.katonahartcenter.com/summer-camps/kids-camp/', NULL, NULL, '914-232-4843', '40-2 Radio Circle Drive', 'Mount Kisco', 'NY', '10549', 'Westchester County, NY', 'specialty', ARRAY['arts']::text[], NULL, NULL, NULL, 3, 18, NULL, 12, 'One week art camps at the Katonah Art Center studio in Mount Kisco, with half day and full day options. Art and Imagination camps serve ages 3.5 to 5, Kids Camp grades 1 to 5 and Teen Camps grades 6 to 12; campers pick one topic for each half day week.', 'both', NULL, 435, 870, 870, 'week', TRUE, NULL, FALSE, NULL, 'Camp cancellations before April 1 are refunded less a $50 processing fee; before May 1, 50% less $50; no refunds after May 1 or for camps booked after May 1. Switching topic or week costs $25. Full refund if the center cancels.', NULL, NULL, NULL, NULL, 2026, '[{"name": "Extended day, morning", "amount": 15, "per": "day", "required": false, "note": "8:30 to 9:30 am, register at least 48 hours ahead for the week"}, {"name": "Extended day, afternoon", "amount": 15, "per": "day", "required": false, "note": "4:30 to 5:30 pm, register at least 48 hours ahead for the week"}]'::jsonb, '14f2f517-54e1-54b8-96ff-f2e889242004', 'katonah-art-center-summer-camps-mount-kisco', ST_GeogFromText('SRID=4326;POINT(-73.7237 41.2023)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.katonahartcenter.com/pages/policies/','https://www.katonahartcenter.com/summer-camps/kids-camp/','https://www.katonahartcenter.com/summer-camps/summer-camps-info/']::text[], '2026-11-27', '2026-11-27', TRUE),
('Lasdon Explorers Summer Program', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/lasdon-explorers-summer-program', 'https://sales.westchestergov.com/webtrac/web/search.html?module=AR&TYPE=LSDN&search=Yes', NULL, NULL, 'Lasdon Public Gardens, 2610 Amawalk Road (Route 35)', 'Katonah', 'NY', '10536', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['arts','outdoor']::text[], ARRAY['nature exploration','art','crafts','games','gardening','pond study','trail walks']::text[], NULL, 5, 12, NULL, NULL, 'County nature camp at Lasdon Public Gardens for ages 5 to 12, three mornings a week (Tuesday to Thursday). Each week has its own theme, from meadows and pond life to garden art and fairy house building, with exploring, crafts and games.', 'outdoor', NULL, 225, 225, 225, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, 'f7f39851-de0a-545c-8dd2-43ef7502bdc8', 'lasdon-explorers-summer-program-katonah', ST_GeogFromText('SRID=4326;POINT(-73.6852 41.2551)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/lasdon-explorers-summer-program']::text[], '2026-11-27', '2026-11-27', TRUE),
('Muscoot Farm Young Wranglers Camp', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/muscoot-farm-young-wranglers-camp', 'https://sales.westchestergov.com/webtrac/web/search.html?module=AR&TYPE=WRANG&search=Yes', NULL, '(914) 864-7286', 'Route 100', 'Somers', 'NY', '10536', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['farm chores','animal care']::text[], NULL, 4, 5, NULL, NULL, 'Half day farm camp at the county''s Muscoot Farm in Somers for children ages 4 and 5. Campers learn about farm life through hands on chores and animal care, in a morning or afternoon group.', 'outdoor', NULL, 225, 225, 225, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, 'e6eca9f1-e483-5e45-91ec-21dde0d505b6', 'muscoot-farm-young-wranglers-camp-somers', ST_GeogFromText('SRID=4326;POINT(-73.7226 41.3044)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/muscoot-farm-young-wranglers-camp','https://parks.westchestercountyny.gov/find-a-park/muscoot-farm']::text[], '2026-11-27', '2026-11-27', TRUE),
('Nike Field Hockey Camp at Manhattanville University', 'US Sports Camps', 'https://www.ussportscamps.com/fieldhockey/nike/manhattanville-university-nike-field-hockey-camp', NULL, NULL, NULL, 'Kennedy Gym, 2900 Purchase Street', 'Harrison', 'NY', '10577', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['field hockey','stick work','goalkeeping','scrimmages']::text[], 'girls', 10, 18, NULL, NULL, 'Four day field hockey day camp at Manhattanville University in Purchase for girls 10 to 18 of all levels, led by the university''s head coach. Morning and afternoon sessions cover stick skills, offense, defense and positioning, with goalkeeper training.', 'outdoor', NULL, 489, 489, 489, 'session', FALSE, FALSE, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, 2027, '[]'::jsonb, '50d63166-a745-5a8e-b16e-c88ba6252bb1', 'nike-field-hockey-camp-manhattanville-purchase', ST_GeogFromText('SRID=4326;POINT(-73.7193 41.0235)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.ussportscamps.com/fieldhockey/nike/manhattanville-university-nike-field-hockey-camp']::text[], '2026-11-27', '2026-11-27', TRUE),
('Nike Running Camp with Hazel Clark at The Hackley School', 'US Sports Camps', 'https://www.ussportscamps.com/track-field/nike/nike-clark-family-running-camp-hackley', NULL, NULL, NULL, '293 Benedict Ave', 'Tarrytown', 'NY', '10591', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['sprints','hurdles','jumps','distance running','cross country','swimming']::text[], 'coed', 10, 17, NULL, NULL, 'Four day track and field and cross country day camp at Hackley School in Tarrytown for ages 10 to 17, run by Olympians Hazel, Joetta and Jearl Miles Clark. Campers train on the 400 meter track and trails in sprints, hurdles, jumps or distance, with a swim to cool down each day.', 'outdoor', NULL, 785, 785, 785, 'session', NULL, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '[]'::jsonb, '8d5c0cb1-1119-57a6-9936-3126a4be51d5', 'nike-running-camp-hazel-clark-hackley-tarrytown', ST_GeogFromText('SRID=4326;POINT(-73.8579 41.0762)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.ussportscamps.com/track-field/nike/nike-clark-family-running-camp-hackley']::text[], '2026-11-27', '2026-11-27', TRUE)
INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, fees, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Nike Volleyball Camp at Hackley School', 'US Sports Camps', 'https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camp-hackley-school', NULL, NULL, NULL, '293 Benedict Avenue', 'Tarrytown', 'NY', '10591', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['volleyball','skills training','game play']::text[], 'girls', 10, 18, NULL, NULL, 'Four day volleyball camp on the indoor courts at Hackley School in Tarrytown for girls 10 to 18. A full day all skills camp builds fundamentals for younger players, and an evening session for ages 14 to 18 works on technique through team play.', 'indoor', NULL, 425, 695, 695, 'session', FALSE, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '[]'::jsonb, '91c28c9b-96b5-5d50-a69a-33161ec691c7', 'nike-volleyball-camp-hackley-tarrytown', ST_GeogFromText('SRID=4326;POINT(-73.8579 41.0762)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camp-hackley-school']::text[], '2026-11-27', '2026-11-27', TRUE),
('Nike Volleyball Camp at Manhattanville University', 'US Sports Camps', 'https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camps-manhattanville-university', NULL, NULL, NULL, '2900 Purchase St', 'Harrison', 'NY', '10577', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['volleyball','skills training','game play']::text[], 'girls', 12, 18, NULL, NULL, 'Four day volleyball camp on the indoor courts at Manhattanville University in Purchase for girls 12 to 18. A full day all skills camp builds fundamentals for players with up to three years of experience, and an evening advanced camp is for players with two or more years of competitive play.', 'indoor', NULL, 295, 595, 595, 'session', FALSE, FALSE, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, 2027, '[]'::jsonb, '2248b241-178b-539a-ae0a-3997fd4ce71a', 'nike-volleyball-camp-manhattanville-purchase', ST_GeogFromText('SRID=4326;POINT(-73.7193 41.0235)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camps-manhattanville-university']::text[], '2026-11-27', '2026-11-27', TRUE),
('No Limit Ninja & Sports Summer Camp', 'No Limit Ninja Yonkers', 'https://www.yonkersninja.com/summercamp', 'https://ecom.roller.app/nolimitninjathemills/summercamp/en-us/home', 'info@yonkersninja.com', '914-714-9814', '222 Lake Ave, 4th Floor', 'Yonkers', 'NY', '10701', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], ARRAY['adventure']::text[], ARRAY['ninja obstacle courses','team sports','free play']::text[], NULL, 5, NULL, NULL, NULL, 'Weekly summer camp at the No Limit Ninja gym in Yonkers for ages 5 and up, mixing ninja obstacle training with team sports in small coached groups, 9 to 3 with before and after care.', NULL, NULL, 599, 599, 599, 'week', TRUE, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[{"name": "Before care", "amount": 15, "per": "day", "required": false, "note": "8 to 9 am"}, {"name": "After care", "amount": 30, "per": "day", "required": false, "note": "3 to 5 pm"}]'::jsonb, '4dc478e7-670d-5082-932a-618a470f41dc', 'no-limit-ninja-and-sports-summer-camp-yonkers', ST_GeogFromText('SRID=4326;POINT(-73.8988 40.9312)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://ecom.roller.app/nolimitninjathemills/summercamp/en-us/home','https://www.yonkersninja.com/summercamp']::text[], '2026-11-27', '2026-11-27', TRUE),
('River Friends Day Camp', 'Shames JCC on the Hudson', 'https://riverfriendsdaycamp.org/', NULL, 'Riverfriends@shamesjcc.org', '914-366-7898', '371 South Broadway', 'Tarrytown', 'NY', '10533', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','sports','nature']::text[], ARRAY['swim','arts and crafts','sports','gardening','music and dance','yoga','karate','obstacle course','water play','shabbat']::text[], NULL, 2, 6, NULL, NULL, 'Day camp for children ages 2 to 6 at the Shames JCC on the Hudson in Tarrytown, with swim lessons, sports, gardening and cooking, water play, yoga, music, dance and crafts. Twos come for a morning or afternoon half day; threes have half and full days and 4 to 6 year olds come 9 to 3.', NULL, 'Jewish', 1550, 6960, NULL, 'session', TRUE, NULL, NULL, NULL, NULL, NULL, 'Upper Camp (4 to 6) has daily free swim and instructional swim lessons by age group.', NULL, NULL, 2027, '[{"name": "Early arrival", "amount": 80, "per": "week", "required": false, "note": "8:00 to 9:15 am, ages 3 and up"}, {"name": "Late stay", "amount": 220, "per": "week", "required": false, "note": "3:00 to 6:00 pm, ages 3 and up"}]'::jsonb, 'b359239a-fc2f-56ce-afee-f1bb13814938', 'river-friends-day-camp-tarrytown', ST_GeogFromText('SRID=4326;POINT(-73.8579 41.0762)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://riverfriendsdaycamp.org/','https://riverfriendsdaycamp.org/4s/5s/6s','https://riverfriendsdaycamp.org/enroll']::text[], '2026-11-27', '2026-11-27', TRUE),
('Sandbox Theatre Summer Camps', 'Sandbox Theatre', 'https://www.wstshows.com/camps', 'https://www.wstshows.com/registration', 'info@wstshows.com', '(914) 670-7768', '300 Waverly Avenue, 2nd Floor', 'Mamaroneck', 'NY', '10543', 'Westchester County, NY', 'specialty', ARRAY['performing_arts']::text[], ARRAY['arts']::text[], ARRAY['acting','singing','dance','improvisation','arts and crafts','scavenger hunts','games','creative writing']::text[], NULL, 5, 14, NULL, NULL, 'One week theater day camps at Sandbox Studios in Mamaroneck, each built around a movie, show or book theme. Campers ages 5 to 14 (each week has its own age band) act, sing, dance, improvise and make crafts, and the week''s work is filmed and sent to families.', 'indoor', NULL, 475, 475, 475, 'week', TRUE, NULL, FALSE, NULL, 'A $225 deposit is due at registration and is not refundable; the balance is due two weeks before camp. Partial weeks are not offered and absences are not prorated.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '17e19c98-32fb-50c5-8687-eea1aeb448d9', 'sandbox-theatre-summer-camps-mamaroneck', ST_GeogFromText('SRID=4326;POINT(-73.734 40.9487)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.wstshows.com/camps']::text[], '2026-11-27', '2026-11-27', TRUE),
('Slam Dunk Basketball Camp', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/slam-dunk-basketball-camp', 'https://sales.westchestergov.com/webtrac/web/search.html?module=AR&TYPE=BASK&search=Yes', NULL, '(914) 231-4645', 'Westchester County Center, 198 Central Avenue', 'White Plains', 'NY', '10606', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['basketball','skill stations','games']::text[], 'coed', 8, 14, 3, 8, 'County basketball day camp at the Westchester County Center in White Plains for boys and girls entering grades 3 to 8. Campers rotate through teaching stations to build skills, then use them in games.', 'indoor', NULL, 375, 425, 425, 'week', NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, '1459678d-bf46-5b39-a46c-516b13dabc84', 'slam-dunk-basketball-camp-white-plains', ST_GeogFromText('SRID=4326;POINT(-73.7629 41.034)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/slam-dunk-basketball-camp']::text[], '2026-11-27', '2026-11-27', TRUE),
('Steffi Nossen SummerDance Camps', 'Steffi Nossen School of Dance', 'https://www.steffinossen.org/summer-dance/summer-camps-rising-1st-5th-graders/', NULL, 'info@steffinossen.org', '914-328-1900', '216 N Central Ave', 'White Plains', 'NY', '10606', 'Westchester County, NY', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['modern dance','ballet','jazz','musical theater','composition','acting','voice']::text[], NULL, 6, 11, 1, 5, 'Week long dance camps for rising 1st to 5th graders at the Steffi Nossen studio in White Plains, with daily technique classes, dance making and a studio performance each Friday. Weeks cover general dance, movie themed dance and musical theater; no experience needed.', 'indoor', NULL, 575, 575, 575, 'week', NULL, NULL, NULL, NULL, 'Tuition is non-refundable, with no refunds or credits for missed classes.', NULL, NULL, NULL, NULL, 2026, '[]'::jsonb, 'ab626c59-0f32-56e3-85da-490a10cbb7e6', 'steffi-nossen-summerdance-camps-white-plains', ST_GeogFromText('SRID=4326;POINT(-73.7629 41.034)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.steffinossen.org/summer-dance/summer-camps-rising-1st-5th-graders/','https://www.steffinossen.org/wp-content/uploads/2026/01/SummerDance-2026-Registration-Form.pdf']::text[], '2026-11-27', '2026-11-27', TRUE)
